@pragma('vm:never-inline')
@pragma('vm:entry-point')
double candidate(String barcode) {
  double oddSum = 0.0;
  double evenSum = 0.0;
  bool isOdd = true;
  for (int i = 0; i < barcode.length; i++) {
    final int digit = barcode.codeUnitAt(i) - 48;
    if (isOdd) {
      oddSum += digit;
    } else {
      evenSum += digit;
    }
    isOdd = !isOdd;
  }
  return oddSum - evenSum;
}

